// EMA's own service worker — intentionally NOT generated by a build tool.
// It only exists to (a) receive Web Push events and show a notification and
// (b) route notification clicks back into "Meine Assistenz". Keep it tiny and
// dependency-free so nothing here can silently swallow a push event.

const NOTIFICATION_ICON = '/icon-192.png'
const NOTIFICATION_BADGE = '/icon-192.png'

self.addEventListener('install', () => {
  self.skipWaiting()
})

self.addEventListener('activate', event => {
  event.waitUntil(self.clients.claim())
})

self.addEventListener('push', event => {
  let payload = {}
  try {
    payload = event.data ? event.data.json() : {}
  } catch (_) {
    payload = { title: 'EMA', body: event.data ? event.data.text() : 'Eine Erinnerung ist fällig.' }
  }

  const title = payload.title || 'EMA'
  const options = {
    body: payload.body || 'Eine Erinnerung ist fällig.',
    icon: NOTIFICATION_ICON,
    badge: NOTIFICATION_BADGE,
    tag: payload.tag || (payload.reminderId ? `ema-reminder-${payload.reminderId}` : 'ema-reminder'),
    renotify: false,
    data: {
      url: payload.url || '/assistant',
      reminderId: payload.reminderId || null,
    },
  }

  event.waitUntil(self.registration.showNotification(title, options))
})

self.addEventListener('notificationclick', event => {
  event.notification.close()
  const targetUrl = new URL(event.notification.data?.url || '/assistant', self.location.origin).href

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(windowClients => {
      for (const client of windowClients) {
        if ('focus' in client) {
          client.navigate(targetUrl)
          return client.focus()
        }
      }
      return self.clients.openWindow ? self.clients.openWindow(targetUrl) : undefined
    })
  )
})
